package ru.neverland.minttrade;
import java.util.*;import ru.neverland.minttrade.integration.TreasuryFunding;import static ru.neverland.minttrade.integration.TreasuryFunding.Result.*;
public final class TreasuryFundingSmoke{
 static final class Item extends org.bukkit.inventory.ItemStack{Item(){super();}@Override public Item clone(){return new Item();}}
 static int checks;static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}static void rejects(Runnable work,String message){try{work.run();}catch(IllegalArgumentException|IllegalStateException expected){checks++;return;}throw new AssertionError(message);}
 public static void main(String[] args){UUID debit=UUID.randomUUID(),refund=UUID.randomUUID(),town=UUID.randomUUID(),actor=UUID.randomUUID();var terms=new TreasuryFunding.Terms(debit,town,actor,22500,"infrastructure","trade","Frozen caravan quote");var receipt=new HashMap<String,Object>();receipt.put("operation",debit.toString());receipt.put("town",town.toString());receipt.put("actor",actor.toString());receipt.put("category","infrastructure");receipt.put("source","trade");receipt.put("reason",terms.reason());receipt.put("owner",TreasuryFunding.OWNER);receipt.put("kind","DEBIT");receipt.put("backingDebit","");receipt.put("cents",22500L);receipt.put("backingAvailable",true);
  for(String pending:List.of("ABSENT","PREPARED","INVOKING")){receipt.put("status",pending);check(terms.result(receipt,debit,false,"")==WAIT,"intent ACK is not permission to deliver cargo");}
  rejects(()->terms.result(Map.of("status","ABSENT","operation",UUID.randomUUID().toString()),debit,false,""),"foreign ABSENT must not authorize a new payment");
  rejects(()->terms.result(Map.of("status","ABSENT"),debit,false,""),"unidentified ABSENT must not authorize a new payment");
  receipt.put("status","REVIEW");check(terms.result(receipt,debit,false,"")==REVIEW,"unknown bank result requires exact reconciliation");receipt.put("status","REJECTED");check(terms.result(receipt,debit,false,"")==NOT_APPLIED,"known unapplied debit can release reservation");receipt.put("status","PAID");check(terms.result(receipt,debit,false,"")==PAID,"exact paid and available escrow permits next durable phase");receipt.put("backingAvailable",false);check(terms.result(receipt,debit,false,"")==REVIEW,"refunded or reserved backing cannot be spent again");receipt.put("backingAvailable",true);
  for(String key:List.of("operation","town","actor","category","source","reason","owner","kind","backingDebit")){var wrong=new HashMap<>(receipt);wrong.put(key,"different");rejects(()->terms.result(wrong,debit,false,""),"same UUID cannot accept changed "+key);}var fractional=new HashMap<>(receipt);fractional.put("cents",22500.5);rejects(()->terms.result(fractional,debit,false,""),"fractional or changed cents cannot pass long truncation");
  receipt.put("operation",refund.toString());receipt.put("kind","REFUND");receipt.put("backingDebit",debit.toString());receipt.put("reason","Original reserve refund");receipt.put("backingAvailable",false);check(terms.result(receipt,refund,true,"Original reserve refund")==PAID,"refund proves original backing and exact original budget payload");rejects(()->terms.result(receipt,UUID.randomUUID(),true,"Original reserve refund"),"another refund ID cannot consume the same confirmation");
  var caravan=new ru.neverland.minttrade.model.Caravan(UUID.randomUUID(),UUID.randomUUID(),town,"stone",new Item(),64,64,200,225,Map.of(UUID.randomUUID(),25D),List.of(),1000,61000,31000,false,false,ru.neverland.minttrade.model.CaravanStatus.ACTIVE);check(caravan.funding()==null&&caravan.fundingProtocol().equals("LEGACY"),"old caravan has no invented Treasury evidence");caravan.fundingActor(actor);var frozen=new TreasuryFunding.Terms(caravan.operation("debit"),town,actor,22500,"infrastructure","trade","Frozen caravan quote");caravan.funding(frozen);check(caravan.copy().funding().equals(frozen)&&caravan.copy().fundingActor().equals(actor),"detached caravan snapshot retains exact funding terms and initiating actor");rejects(caravan::directFunding,"Treasury reserve cannot fall back to direct bank mutation");rejects(()->caravan.fundingActor(UUID.randomUUID()),"funding initiator is immutable");rejects(()->caravan.funding(new TreasuryFunding.Terms(caravan.operation("debit"),town,actor,22501,"infrastructure","trade","Frozen caravan quote")),"funding must equal complete frozen caravan escrow");rejects(()->caravan.funding(new TreasuryFunding.Terms(UUID.randomUUID(),town,actor,22500,"infrastructure","trade","Frozen caravan quote")),"funding must use stable caravan debit operation");
  System.out.println("TreasuryFundingSmoke PASS "+checks+" checks");
 }
}
